# -*- coding: utf-8 -*-

"""Step 02 — Extract ordered master cut curves on X0/Y0/Z0.

Purpose
-------
Convert the free edges of the cut-cell Marching-Cubes surface into ordered
polyline components on the three master faces.  Only master faces are retained;
opposite faces will be generated by periodicity later.

Input : cases/<case>/periodic_topology.npz
Outputs: master_boundary_curves.npz, master_boundary_report.json
"""
import json

import numpy as np


# ============================================================
# Central configuration
# ============================================================

from meshlib.config import CFG
from meshlib.flags import X0, XL, Y0, YL, Z0, ZL, FLAG_INFO, MASTER_FACES

CASE_ID = CFG.case_id
CASE_DIR = CFG.case_dir
INPUT_FILE = CASE_DIR / "periodic_topology.npz"
OUTPUT_NPZ = CASE_DIR / "master_boundary_curves.npz"
OUTPUT_JSON = CASE_DIR / "master_boundary_report.json"


# ============================================================
# Basic mesh edge extraction
# ============================================================

def build_edges(faces):

    edges = np.vstack(
        [
            faces[:, [0, 1]],
            faces[:, [1, 2]],
            faces[:, [2, 0]],
        ]
    )

    edges = np.sort(
        edges,
        axis=1
    )

    unique_edges = np.unique(
        edges,
        axis=0
    )

    return unique_edges


def get_boundary_edges(
    edges,
    boundary_flags,
    face_flag,
):

    mask = (
        ((boundary_flags[edges[:, 0]]
          & face_flag) != 0)
        &
        ((boundary_flags[edges[:, 1]]
          & face_flag) != 0)
    )

    return edges[mask]


# ============================================================
# Boundary flag decoding
# ============================================================

def decode_flags(flag_value):

    labels = []

    for name, flag in FLAG_INFO:

        if (flag_value & flag) != 0:
            labels.append(name)

    return labels


def endpoint_location_string(
    boundary_flags,
    node_id,
):

    labels = decode_flags(
        boundary_flags[node_id]
    )

    if len(labels) == 0:
        return "INTERIOR"

    return "&".join(labels)


# ============================================================
# Graph construction
# ============================================================

def build_adjacency(edges):

    adjacency = {}

    for a, b in edges:

        a = int(a)
        b = int(b)

        adjacency.setdefault(
            a,
            set()
        ).add(b)

        adjacency.setdefault(
            b,
            set()
        ).add(a)

    return adjacency


def connected_components(adjacency):

    visited = set()
    components = []

    for start in sorted(adjacency):

        if start in visited:
            continue

        stack = [start]
        visited.add(start)

        comp = []

        while stack:

            u = stack.pop()
            comp.append(u)

            for v in adjacency[u]:

                if v not in visited:

                    visited.add(v)
                    stack.append(v)

        components.append(
            sorted(comp)
        )

    return components


# ============================================================
# Deterministic node ordering key
# ============================================================

def node_key(vertices, node_id):

    xyz = vertices[node_id]

    return (
        float(xyz[0]),
        float(xyz[1]),
        float(xyz[2]),
        int(node_id),
    )


# ============================================================
# Convert one graph component into ordered polyline
# ============================================================

def order_component(
    vertices,
    adjacency,
    component_nodes,
):

    comp_set = set(
        component_nodes
    )

    local_adj = {}

    for node in component_nodes:

        local_adj[node] = [
            n
            for n in adjacency[node]
            if n in comp_set
        ]

    degrees = {
        node: len(neigh)
        for node, neigh
        in local_adj.items()
    }

    degree1 = [
        node
        for node, deg
        in degrees.items()
        if deg == 1
    ]

    bad_degree = [
        node
        for node, deg
        in degrees.items()
        if deg > 2 or deg == 0
    ]

    if len(bad_degree) > 0:

        raise RuntimeError(
            "Boundary component contains "
            "branching or isolated node(s): "
            f"{bad_degree[:10]}"
        )

    # --------------------------------------------------------
    # Open curve
    # --------------------------------------------------------

    if len(degree1) == 2:

        closed = False

        start = min(
            degree1,
            key=lambda i:
                node_key(vertices, i)
        )

        end_expected = (
            degree1[0]
            if degree1[1] == start
            else degree1[1]
        )

        ordered = [start]

        previous = None
        current = start

        while True:

            candidates = [
                n
                for n in local_adj[current]
                if n != previous
            ]

            if len(candidates) == 0:
                break

            if len(candidates) != 1:

                raise RuntimeError(
                    "Unexpected branching while "
                    "ordering open curve."
                )

            nxt = candidates[0]

            ordered.append(nxt)

            previous = current
            current = nxt

        if ordered[-1] != end_expected:

            raise RuntimeError(
                "Open curve traversal did not "
                "terminate at expected endpoint."
            )

        if len(set(ordered)) != len(component_nodes):

            raise RuntimeError(
                "Open curve traversal did not "
                "visit all nodes exactly once."
            )

        return (
            np.asarray(
                ordered,
                dtype=np.int64
            ),
            closed
        )

    # --------------------------------------------------------
    # Closed curve
    # --------------------------------------------------------

    if len(degree1) == 0:

        closed = True

        # deterministic starting vertex
        start = min(
            component_nodes,
            key=lambda i:
                node_key(vertices, i)
        )

        neighbours = local_adj[start]

        if len(neighbours) != 2:

            raise RuntimeError(
                "Closed curve start node "
                "does not have degree 2."
            )

        # deterministic orientation
        first = min(
            neighbours,
            key=lambda i:
                node_key(vertices, i)
        )

        ordered = [
            start,
            first
        ]

        previous = start
        current = first

        while True:

            candidates = [
                n
                for n in local_adj[current]
                if n != previous
            ]

            if len(candidates) != 1:

                raise RuntimeError(
                    "Unexpected branching while "
                    "ordering closed curve."
                )

            nxt = candidates[0]

            if nxt == start:
                break

            if nxt in ordered:

                raise RuntimeError(
                    "Closed curve entered a loop "
                    "before returning to start."
                )

            ordered.append(nxt)

            previous = current
            current = nxt

        if len(ordered) != len(component_nodes):

            raise RuntimeError(
                "Closed curve traversal did not "
                "visit all nodes."
            )

        return (
            np.asarray(
                ordered,
                dtype=np.int64
            ),
            closed
        )

    raise RuntimeError(
        "Boundary component is neither "
        "a valid open curve nor a closed curve. "
        f"Number of degree-1 nodes = {len(degree1)}"
    )


# ============================================================
# Curve geometry
# ============================================================

def curve_segment_lengths(
    vertices,
    ordered_ids,
    closed,
):

    xyz = vertices[ordered_ids]

    segments = np.linalg.norm(
        xyz[1:] - xyz[:-1],
        axis=1
    )

    if closed:

        closing = np.linalg.norm(
            xyz[0] - xyz[-1]
        )

        segments = np.concatenate(
            [
                segments,
                np.array(
                    [closing],
                    dtype=float
                ),
            ]
        )

    return segments


def curve_length(
    vertices,
    ordered_ids,
    closed,
):

    segments = curve_segment_lengths(
        vertices,
        ordered_ids,
        closed,
    )

    return float(
        np.sum(segments)
    )


# ============================================================
# Validate endpoint is actually on a cube edge
# ============================================================

def validate_open_endpoints(
    boundary_flags,
    ordered_ids,
):

    for node_id in (
        int(ordered_ids[0]),
        int(ordered_ids[-1]),
    ):

        labels = decode_flags(
            boundary_flags[node_id]
        )

        # A curve on one cube face should end
        # on another cube face, therefore at
        # least two boundary flags are expected.
        if len(labels) < 2:

            raise RuntimeError(
                "Open boundary curve endpoint "
                "is not on a cube edge. "
                f"node={node_id}, flags={labels}"
            )


# ============================================================
# Main
# ============================================================

def main():

    print()
    print(
        "================================================"
    )
    print(
        "MASTER PERIODIC BOUNDARY BUILDER"
    )
    print(
        "================================================"
    )

    data = np.load(
        INPUT_FILE
    )

    vertices = data[
        "vertices"
    ].astype(np.float64)

    faces = data[
        "faces"
    ].astype(np.int64)

    boundary_flags = data[
        "boundary_flags"
    ]

    periodic_class = data[
        "periodic_class"
    ]

    edges = build_edges(
        faces
    )

    all_curve_ids = []
    all_curve_offsets = [0]

    all_curve_faces = []
    all_curve_closed = []
    all_curve_lengths = []

    report_curves = []

    global_curve_index = 0

    # --------------------------------------------------------
    # Only X0, Y0, Z0 are master faces.
    #
    # XL/YL/ZL will later be generated
    # strictly by periodic translation.
    # --------------------------------------------------------

    for face_index, (
        face_name,
        face_flag
    ) in enumerate(MASTER_FACES):

        boundary_edges = (
            get_boundary_edges(
                edges,
                boundary_flags,
                face_flag,
            )
        )

        adjacency = build_adjacency(
            boundary_edges
        )

        components = (
            connected_components(
                adjacency
            )
        )

        print()
        print(
            "---------------------------------------------"
        )
        print(
            f"MASTER FACE {face_name}"
        )
        print(
            "---------------------------------------------"
        )

        print(
            "boundary edges =",
            len(boundary_edges)
        )

        print(
            "curve components =",
            len(components)
        )

        # Deterministic component ordering
        components = sorted(
            components,
            key=lambda comp:
                min(
                    node_key(
                        vertices,
                        i
                    )
                    for i in comp
                )
        )

        for local_index, comp in enumerate(
            components
        ):

            ordered_ids, closed = (
                order_component(
                    vertices,
                    adjacency,
                    comp,
                )
            )

            if not closed:

                validate_open_endpoints(
                    boundary_flags,
                    ordered_ids,
                )

            segments = (
                curve_segment_lengths(
                    vertices,
                    ordered_ids,
                    closed,
                )
            )

            length = float(
                np.sum(segments)
            )

            curve_name = (
                f"{face_name}_curve_"
                f"{local_index:03d}"
            )

            start_id = int(
                ordered_ids[0]
            )

            end_id = (
                int(ordered_ids[-1])
                if not closed
                else start_id
            )

            start_location = (
                endpoint_location_string(
                    boundary_flags,
                    start_id,
                )
            )

            end_location = (
                endpoint_location_string(
                    boundary_flags,
                    end_id,
                )
            )

            start_class = int(
                periodic_class[start_id]
            )

            end_class = int(
                periodic_class[end_id]
            )

            print()
            print(curve_name)

            print(
                "  type          =",
                "CLOSED"
                if closed
                else "OPEN"
            )

            print(
                "  nodes         =",
                len(ordered_ids)
            )

            print(
                "  segments      =",
                len(segments)
            )

            print(
                "  total length  =",
                length
            )

            print(
                "  segment min   =",
                float(
                    np.min(segments)
                )
            )

            print(
                "  segment mean  =",
                float(
                    np.mean(segments)
                )
            )

            print(
                "  segment max   =",
                float(
                    np.max(segments)
                )
            )

            if not closed:

                print(
                    "  start node    =",
                    start_id
                )

                print(
                    "  start location=",
                    start_location
                )

                print(
                    "  start pclass  =",
                    start_class
                )

                print(
                    "  end node      =",
                    end_id
                )

                print(
                    "  end location  =",
                    end_location
                )

                print(
                    "  end pclass    =",
                    end_class
                )

            # -----------------------------------------------
            # Store canonical packed representation
            # -----------------------------------------------

            all_curve_ids.extend(
                ordered_ids.tolist()
            )

            all_curve_offsets.append(
                len(all_curve_ids)
            )

            all_curve_faces.append(
                face_index
            )

            all_curve_closed.append(
                closed
            )

            all_curve_lengths.append(
                length
            )

            curve_report = {

                "global_curve_index":
                    global_curve_index,

                "name":
                    curve_name,

                "master_face":
                    face_name,

                "closed":
                    bool(closed),

                "n_nodes":
                    int(
                        len(ordered_ids)
                    ),

                "n_segments":
                    int(
                        len(segments)
                    ),

                "length_mm":
                    length,

                "segment_min_mm":
                    float(
                        np.min(segments)
                    ),

                "segment_mean_mm":
                    float(
                        np.mean(segments)
                    ),

                "segment_median_mm":
                    float(
                        np.median(segments)
                    ),

                "segment_max_mm":
                    float(
                        np.max(segments)
                    ),

                "segment_lt_002":
                    int(
                        np.count_nonzero(
                            segments < 0.02
                        )
                    ),

                "segment_lt_005":
                    int(
                        np.count_nonzero(
                            segments < 0.05
                        )
                    ),

                "start_node":
                    start_id,

                "end_node":
                    end_id,

                "start_location":
                    start_location,

                "end_location":
                    end_location,

                "start_periodic_class":
                    start_class,

                "end_periodic_class":
                    end_class,
            }

            report_curves.append(
                curve_report
            )

            global_curve_index += 1

    # --------------------------------------------------------
    # Cross-face endpoint consistency check
    #
    # If X0 and Y0 curves meet on the same
    # cube edge, they must refer to the same
    # actual topology node or periodic class.
    # --------------------------------------------------------

    open_endpoints = []

    for curve in report_curves:

        if curve["closed"]:
            continue

        open_endpoints.append(
            (
                curve["name"],
                "start",
                curve["start_node"],
                curve[
                    "start_periodic_class"
                ],
                curve["start_location"],
            )
        )

        open_endpoints.append(
            (
                curve["name"],
                "end",
                curve["end_node"],
                curve[
                    "end_periodic_class"
                ],
                curve["end_location"],
            )
        )

    endpoint_classes = {}

    for (
        curve_name,
        side,
        node_id,
        pclass,
        location
    ) in open_endpoints:

        endpoint_classes.setdefault(
            pclass,
            []
        ).append(
            {
                "curve":
                    curve_name,

                "side":
                    side,

                "node":
                    int(node_id),

                "location":
                    location,
            }
        )

    shared_classes = {
        str(k): v
        for k, v in endpoint_classes.items()
        if len(v) > 1
    }

    print()
    print(
        "================================================"
    )
    print(
        "CROSS-FACE ENDPOINT CLASSES"
    )
    print(
        "================================================"
    )

    if len(shared_classes) == 0:

        print(
            "No master-face endpoint classes "
            "are shared."
        )

    else:

        for pclass, entries in (
            shared_classes.items()
        ):

            print()
            print(
                "Periodic class",
                pclass
            )

            for entry in entries:

                print(
                    " ",
                    entry
                )

    # --------------------------------------------------------
    # Save packed curve representation
    # --------------------------------------------------------

    np.savez_compressed(

        OUTPUT_NPZ,

        curve_vertex_ids=np.asarray(
            all_curve_ids,
            dtype=np.int64
        ),

        curve_offsets=np.asarray(
            all_curve_offsets,
            dtype=np.int64
        ),

        curve_face_id=np.asarray(
            all_curve_faces,
            dtype=np.int8
        ),

        curve_closed=np.asarray(
            all_curve_closed,
            dtype=bool
        ),

        curve_length_mm=np.asarray(
            all_curve_lengths,
            dtype=np.float64
        ),

        master_face_names=np.asarray(
            [
                "X0",
                "Y0",
                "Z0"
            ]
        )
    )

    report = {

        "case_id":
            CASE_ID,

        "n_master_curves":
            int(
                len(report_curves)
            ),

        "n_x0_curves":
            int(
                sum(
                    c["master_face"]
                    == "X0"
                    for c in report_curves
                )
            ),

        "n_y0_curves":
            int(
                sum(
                    c["master_face"]
                    == "Y0"
                    for c in report_curves
                )
            ),

        "n_z0_curves":
            int(
                sum(
                    c["master_face"]
                    == "Z0"
                    for c in report_curves
                )
            ),

        "curves":
            report_curves,

        "shared_endpoint_classes":
            shared_classes,
    }

    with OUTPUT_JSON.open(
        "w",
        encoding="utf-8"
    ) as f:

        json.dump(
            report,
            f,
            indent=2,
            ensure_ascii=False
        )

    print()
    print(
        "Saved:"
    )

    print(
        " ",
        OUTPUT_NPZ
    )

    print(
        " ",
        OUTPUT_JSON
    )

    print()
    print(
        "================================================"
    )
    print(
        "MASTER BOUNDARY STATUS: PASS"
    )
    print(
        "================================================"
    )


if __name__ == "__main__":
    main()